div.script:
                (function(){
                    var wrap = document.querySelector('.ck-wrap');
                    var KID = wrap.getAttribute('data-kiosk');
                    var TIMEOUT = (parseInt(wrap.getAttribute('data-timeout'))||90)*1000;
                    var idleTimer = null, pollTimer = null;

                    function rpc(path, params){
                        return fetch('/care/kiosk/'+KID+path, {
                            method:'POST', headers:{'Content-Type':'application/json'},
                            body: JSON.stringify({jsonrpc:'2.0', method:'call', params: params||{}})
                        }).then(function(r){return r.json();}).then(function(j){return j.result||{};});
                    }
                    function show(id){
                        ['ck-scan','ck-menu','ck-view'].forEach(function(x){
                            document.getElementById(x).style.display = (x===id)?'block':'none';
                        });
                    }
                    function resetIdle(){
                        if(idleTimer) clearTimeout(idleTimer);
                        idleTimer = setTimeout(function(){ ckLogout(); }, TIMEOUT);
                    }
                    window.ckLogout = function(){
                        rpc('/logout',{}).then(function(){
                            show('ck-scan');
                            document.getElementById('ck-scan-msg').innerText='بانتظار مسح البصمة…';
                            startPoll();
                        });
                    };
                    window.ckHome = function(){ show('ck-menu'); resetIdle(); };
                    window.ckPanel = function(panel, title){
                        resetIdle();
                        document.getElementById('ck-view-title').innerText = title;
                        document.getElementById('ck-view-body').innerHTML = '
جارٍ التحميل…';
                        show('ck-view');
                        rpc('/panel',{panel:panel}).then(function(res){
                            if(!res.ok){ ckLogout(); return; }
                            var items = res.items||[]; var h='';
                            if(!items.length){ h = '
لا يوجد.'; }
                            items.forEach(function(it){
                                if(panel==='payslips') h+='
'+(it.name||'')+''+(it.period||'')+' · '+(it.net||'')+'';
                                else if(panel==='docs') h+='
'+(it.name||'')+''+(it.category||'')+' · '+(it.date||'')+'';
                                else h+='
'+(it.name||'')+'
'+(it.body||'')+'';
                            });
                            document.getElementById('ck-view-body').innerHTML = h;
                        });
                    };
                    window.ckReq = function(kind, title){
                        resetIdle();
                        document.getElementById('ck-view-title').innerText = title;
                        document.getElementById('ck-view-body').innerHTML =
                            ''+
                            'إرسال'+
                            '
';
                        show('ck-view');
                    };
                    window.ckSend = function(kind){
                        var note = (document.getElementById('ck-note')||{}).value||'';
                        rpc('/request',{kind:kind, note:note}).then(function(res){
                            var m = document.getElementById('ck-req-msg');
                            if(res.ok){ m.innerText='✅ تم الإرسال: '+(res.ref||''); setTimeout(ckHome,1500); }
                            else { m.innerText='تعذّر الإرسال.'; }
                        });
                        resetIdle();
                    };
                    function onIdentified(res){
                        if(pollTimer){ clearInterval(pollTimer); pollTimer=null; }
                        document.getElementById('ck-name').innerText = res.name||'';
                        document.getElementById('ck-job').innerText = (res.job||'')+(res.department?(' · '+res.department):'');
                        document.getElementById('ck-img').src = res.image||'';
                        show('ck-menu'); resetIdle();
                    }
                    function startPoll(){
                        if(pollTimer) clearInterval(pollTimer);
                        pollTimer = setInterval(function(){
                            rpc('/identify',{}).then(function(res){ if(res.found) onIdentified(res); });
                        }, 2000);
                    }
                    ['click','touchstart','keydown'].forEach(function(ev){
                        document.addEventListener(ev, function(){ if(idleTimer) resetIdle(); });
                    });
                    startPoll();
                })();
